import { useEffect, useState } from "react";
import io from "socket.io-client";

export default function Dashboard() {
  const [botStatus, setBotStatus] = useState("disconnected");
  const [contractBalance, setContractBalance] = useState("0");
  const [newTokens, setNewTokens] = useState([]);
  const [portfolioValue, setPortfolioValue] = useState("0.00");
  const [profit, setProfit] = useState("+0.00");

  // Connect to backend
  useEffect(() => {
    const socket = io("http://localhost:4001"); // must match server.js port

    socket.on("bot_status", (data) => {
      setBotStatus(data.status);
    });

    socket.on("contract_balance", (data) => {
      setContractBalance(data.balance);
    });

    socket.on("new_token", (token) => {
      setNewTokens((prev) => [token, ...prev.slice(0, 4)]);
    });

    socket.on("portfolio", (data) => {
      setPortfolioValue(data.value);
      setProfit(data.profit);
    });

    return () => socket.disconnect();
  }, []);

  const startBot = async () => {
    await fetch("http://localhost:4001/start");
    setBotStatus("live");
  };

  const stopBot = async () => {
    await fetch("http://localhost:4001/stop");
    setBotStatus("stopped");
  };

  return (
    <div className="dashboard-container">
      <header>
        <h1>ArchAngel Trading Dashboard</h1>
        <p>Track trades, monitor profit, and manage your trading bot in real time.</p>
      </header>

      <div className="stats">
        <div className="card">
          <h3>Portfolio Value</h3>
          <p className="value">${portfolioValue}</p>
        </div>
        <div className="card">
          <h3>Total Profit</h3>
          <p className="profit">{profit}</p>
        </div>
        <div className="card">
          <h3>Bot Status</h3>
          <p
            className={`status ${
              botStatus === "live" ? "live" : botStatus === "stopped" ? "stopped" : "disconnected"
            }`}
          >
            {botStatus.toUpperCase()}
          </p>
        </div>
        <div className="card">
          <h3>CA Balance</h3>
          <p className="value">{contractBalance} ETH</p>
        </div>
      </div>

      <div className="controls">
        <button
          onClick={startBot}
          className={`btn ${botStatus === "live" ? "disabled" : ""}`}
          disabled={botStatus === "live"}
        >
          ▶ Start Bot
        </button>
        <button
          onClick={stopBot}
          className={`btn stop ${botStatus !== "live" ? "disabled" : ""}`}
          disabled={botStatus !== "live"}
        >
          ⏹ Stop Bot
        </button>
      </div>

      <section className="new-tokens">
        <h2>🪙 New Token Discoveries</h2>
        {newTokens.length === 0 ? (
          <p>No new tokens detected yet...</p>
        ) : (
          <table>
            <thead>
              <tr>
                <th>Token</th>
                <th>Pair</th>
                <th>Liquidity</th>
                <th>Detected</th>
              </tr>
            </thead>
            <tbody>
              {newTokens.map((t, i) => (
                <tr key={i}>
                  <td>{t.symbol || "Unknown"}</td>
                  <td>{t.address.slice(0, 6)}...{t.address.slice(-4)}</td>
                  <td>{t.liquidity || "N/A"}</td>
                  <td>{new Date().toLocaleTimeString()}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </section>
    </div>
  );
}
